{
  "id": "220ab1e7-d852-4fa7-b920-95e1957d01b3",
  "version": "1.8",
  "name": "MultiCityWeather",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Manual trigger"
      },
      "inputs": {
        "entryPointId": "adeec193-bbfa-4e5d-89d0-011150a83bc2",
        "isDefaultEntryPoint": true
      }
    },
    {
      "id": "loop1",
      "type": "core.logic.loop",
      "typeVersion": "2.4",
      "display": {
        "label": "Loop over cities"
      },
      "inputs": {
        "collection": "=js:[{name:'Seattle',lat:47.6062,lon:-122.3321},{name:'Phoenix',lat:33.4484,lon:-112.074},{name:'New York',lat:40.7128,lon:-74.006}]",
        "parallel": false
      }
    },
    {
      "id": "fetchWeather1",
      "type": "core.action.http.v2",
      "typeVersion": "2.3",
      "display": {
        "label": "Fetch Weather"
      },
      "inputs": {
        "branches": [],
        "timeout": "PT15M",
        "retryCount": 0
      },
      "parentId": "loop1"
    },
    {
      "id": "classify1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Classify Temperature"
      },
      "inputs": {
        "script": "var city = $vars.loop1.currentItem.name;\nvar body = $vars.fetchWeather1.output.body;\nvar temp = body && body.current_weather ? body.current_weather.temperature : null;\nvar verdict = temp > 60 ? 'warm' : 'cold';\nreturn { city: city, temperature: temp, verdict: verdict };"
      },
      "parentId": "loop1"
    },
    {
      "id": "end1",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "End"
      },
      "inputs": {},
      "outputs": {
        "weatherResults": {
          "source": "=js:$vars.results"
        }
      }
    }
  ],
  "edges": [
    {
      "id": "e-start-loop1",
      "sourceNodeId": "start",
      "sourcePort": "output",
      "targetNodeId": "loop1",
      "targetPort": "input"
    },
    {
      "id": "e-loop1-fetch",
      "sourceNodeId": "loop1",
      "sourcePort": "start",
      "targetNodeId": "fetchWeather1",
      "targetPort": "input"
    },
    {
      "id": "e-fetch-classify",
      "sourceNodeId": "fetchWeather1",
      "sourcePort": "default",
      "targetNodeId": "classify1",
      "targetPort": "input"
    },
    {
      "id": "e-classify-loop",
      "sourceNodeId": "classify1",
      "sourcePort": "success",
      "targetNodeId": "loop1",
      "targetPort": "continue"
    },
    {
      "id": "e-loop-end",
      "sourceNodeId": "loop1",
      "sourcePort": "success",
      "targetNodeId": "end1",
      "targetPort": "input"
    }
  ],
